package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;

/** Supervised requests create authority only through an explicit atomic approval. Observations are inert. */
public final class DelegationService {
    @FunctionalInterface public interface Materializer {ObjectNode create(Connection c,ObjectNode pipeline,JsonNode input,Instant deadline)throws Exception;}
    @FunctionalInterface public interface Canceller {void cancel(String executionId)throws Exception;}
    private final Db db;private final PolicyService policy;private Materializer materializer;private Canceller canceller;
    public DelegationService(Db db,PolicyService policy){this.db=db;this.policy=policy;}
    public void bindExecutions(Materializer materializer,Canceller canceller){this.materializer=Objects.requireNonNull(materializer);this.canceller=Objects.requireNonNull(canceller);}
    public ObjectNode request(JsonNode input){return db.transaction(t->requestWithManager(t.connection(),input));}
    public ObjectNode requestWithManager(Connection c,JsonNode input){Db t=Db.on(c);ObjectNode payload=Json.object();for(String field:List.of("parentExecutionId","parentAttemptId","requestId","requestedAgent"))payload.put(field,BudgetDomain.bounded(input.get(field),255,field));Instant due;try{due=Instant.parse(Json.text(input,"expiresAt"));}catch(RuntimeException e){throw new IllegalArgumentException("expiresAt must be a valid instant");}payload.put("expiresAt",due.toString());String hash=Json.hash(payload);ObjectNode attempt=t.one("SELECT * FROM step_attempts WHERE id=?::uuid FOR UPDATE",payload.get("parentAttemptId"));if(attempt==null||!attempt.path("executionId").equals(payload.get("parentExecutionId")))throw new IllegalArgumentException("Delegation attempt does not belong to declared parent execution");ObjectNode existing=t.one("SELECT * FROM delegation_requests WHERE \"parentAttemptId\"=?::uuid AND \"requestId\"=?",payload.get("parentAttemptId"),payload.get("requestId"));if(existing!=null){if(!hash.equals(Json.text(existing,"payloadHash"))){t.insert("delegation_request_conflicts",Json.object("parentAttemptId",payload.get("parentAttemptId"),"requestId",payload.get("requestId"),"payloadHash",hash,"payload",payload,"conflictKind",existing.hasNonNull("payloadHash")?"PAYLOAD_MISMATCH":"LEGACY_PAYLOAD_UNKNOWN"));return Json.object("disposition","conflict","request",existing);}return Json.object("disposition","replayed","request",existing);}int live=count(t,"SELECT COUNT(*) n FROM delegation_requests WHERE \"parentAttemptId\"=?::uuid AND status IN ('PENDING','APPROVED')",payload.get("parentAttemptId"));if(live>=10)throw new IllegalArgumentException("Delegation fanout exceeds 10");int depth=parentDepth(t,Json.text(payload,"parentExecutionId"))+1;if(depth>3)throw new IllegalArgumentException("Delegation depth exceeds 3");Integer runMax=runDepth(t,Json.text(payload,"parentExecutionId"));if(runMax!=null&&depth>runMax)throw new IllegalArgumentException("Delegation depth exceeds frozen coordination bound");ObjectNode fields=payload.deepCopy();fields.remove("expiresAt");fields.put("expiresAt",due.toString());fields.put("payloadHash",hash);fields.put("childDepth",depth);fields.putNull("childExecutionId");fields.put("status","PENDING");fields.set("authorityDeadlineAt",Json.get(attempt,"deadlineAt"));ObjectNode saved=t.insert("delegation_requests",fields);return Json.object("disposition","created","request",saved);}
    public ObjectNode approve(String attempt,String requestId,ObjectNode pipeline){return db.transaction(t->{ObjectNode r=lock(t,attempt,requestId);if(!"PENDING".equals(Json.text(r,"status")))return outcome(r);Instant now=Instant.now();if(!Instant.parse(Json.text(r,"expiresAt")).isAfter(now))return decide(t,r,"EXPIRED","Delegation request expired before approval",null);if(r.hasNonNull("authorityDeadlineAt")&&!Instant.parse(Json.text(r,"authorityDeadlineAt")).isAfter(now))return decide(t,r,"EXPIRED","Parent attempt authority deadline elapsed before child approval",null);int depth=Json.integer(r,"childDepth",1);Integer max=runDepth(t,Json.text(r,"parentExecutionId"));if(depth>3||(max!=null&&depth>max))return decide(t,r,"REJECTED","Delegation depth exceeds authority bound",null);if(policy.isConfigured()){JsonNode d=policy.evaluate(PolicyDomain.delegation("delegate:"+Json.text(r,"id"),Json.text(r,"parentExecutionId"),Json.text(r,"requestedAgent")),t.connection());if("DENY".equals(Json.text(d,"effect")))return decide(t,r,"REJECTED","Policy DENY: "+Json.stringify(d.get("reasons")),null);}JsonNode childBudget;try{childBudget=BudgetDomain.pipelineBudget(pipeline.get("budget"));if(childBudget.isNull())for(JsonNode s:pipeline.path("steps"))if(s.has("budget"))throw new IllegalArgumentException("Budgeted child steps require an explicit pipeline grant");if(!childBudget.isNull()){ObjectNode parent=t.one("SELECT * FROM budget_accounts WHERE \"scopeType\"='execution' AND \"scopeId\"=?",r.get("parentExecutionId"));if(parent==null)throw new IllegalArgumentException("Parent execution has no budget grant");BudgetLedgerService.subset(childBudget.path("ceilings"),parent);}}catch(RuntimeException e){return decide(t,r,"REJECTED",e.getMessage(),null);}if(materializer==null)throw new IllegalStateException("Delegation execution materializer is not bound");ObjectNode governed=pipeline.deepCopy();if(!childBudget.isNull()){ObjectNode b=(ObjectNode)childBudget.deepCopy();b.set("parent",Json.object("scopeType","execution","scopeId",r.get("parentExecutionId")));governed.set("budget",b);governed.put("contentHash","");}ObjectNode child=materializer.create(t.connection(),governed,Json.object("delegatedFrom",r.get("parentExecutionId")),r.hasNonNull("authorityDeadlineAt")?Instant.parse(Json.text(r,"authorityDeadlineAt")):null);return decide(t,r,"APPROVED","Child execution "+Json.text(child,"id")+" materialized",Json.text(child,"id"));});}
    public ObjectNode reject(String attempt,String request,String note){return db.transaction(t->{ObjectNode r=lock(t,attempt,request);return "PENDING".equals(Json.text(r,"status"))?decide(t,r,"REJECTED",note,null):outcome(r);});}
    public ObjectNode projection(String execution,int limit,Connection c){Db t=c==null?db:Db.on(c);limit=Math.max(0,Math.min(1000,limit));List<ObjectNode> supervised=t.query("SELECT \"requestId\",\"childExecutionId\",\"childDepth\",\"requestedAgent\",status FROM delegation_requests WHERE \"parentExecutionId\"=?::uuid AND \"childExecutionId\" IS NOT NULL ORDER BY \"createdAt\",id LIMIT ?",execution,limit+1),observed=t.query("SELECT \"observationId\",provider,\"childId\",\"stepAttemptId\",\"occurredAt\" FROM delegation_observations WHERE \"executionId\"=?::uuid ORDER BY \"receivedAt\",id LIMIT ?",execution,limit+1);boolean st=supervised.size()>limit,ot=observed.size()>limit;if(st)supervised.remove(supervised.size()-1);if(ot)observed.remove(observed.size()-1);return Json.object("executionId",execution,"depth",parentDepth(t,execution),"supervised",supervised,"observed",observed,"supervisedTotal",count(t,"SELECT COUNT(*) n FROM delegation_requests WHERE \"parentExecutionId\"=?::uuid AND \"childExecutionId\" IS NOT NULL",execution),"observedTotal",count(t,"SELECT COUNT(*) n FROM delegation_observations WHERE \"executionId\"=?::uuid",execution),"supervisedTruncated",st,"observedTruncated",ot);}
    public int cancelOrphans(int limit){if(canceller==null)throw new IllegalStateException("Delegation cancellation is not bound");List<ObjectNode> rows=db.query("SELECT r.\"childExecutionId\" FROM delegation_requests r JOIN executions p ON p.id=r.\"parentExecutionId\" JOIN executions child ON child.id=r.\"childExecutionId\" WHERE r.status='APPROVED' AND p.status='CANCELLED' AND child.status NOT IN ('CANCELLED','COMPLETED','FAILED') ORDER BY r.\"createdAt\",r.id LIMIT ?",Math.max(0,Math.min(1000,limit)));int n=0;for(ObjectNode row:rows)try{canceller.cancel(Json.text(row,"childExecutionId"));n++;}catch(Exception error){System.err.println("Delegation orphan cancellation failed for child "+Json.text(row,"childExecutionId"));}return n;}
    public int expireDue(Connection c,Instant now,int limit){return (c==null?db:Db.on(c)).transaction(t->{List<ObjectNode> rows=t.query("SELECT * FROM delegation_requests WHERE status='PENDING' AND \"expiresAt\"<=? ORDER BY \"expiresAt\",id LIMIT ? FOR UPDATE SKIP LOCKED",now,Math.max(0,Math.min(1000,limit)));for(ObjectNode r:rows)decide(t,r,"EXPIRED","Delegation request expired",null);return rows.size();});}
    public void recordObservations(Connection c,ObjectNode attempt,ObjectNode step,JsonNode observations){if(!"observed".equals(Json.text(step,"delegation"))||observations==null||!observations.isArray()||observations.isEmpty())return;Db t=Db.on(c);Savepoint checkpoint=null;try{checkpoint=c.setSavepoint();for(JsonNode o:observations){String provider=BudgetDomain.bounded(o.get("provider"),64,"provider"),child=BudgetDomain.bounded(o.get("childId"),255,"childId"),id=provider+":"+child,hash=Json.hash(o);Instant occurred=Instant.parse(Json.text(o,"assertedAt"));t.execute("INSERT INTO delegation_observations (\"stepAttemptId\",\"invocationId\",\"executionId\",\"observationId\",provider,\"childId\",\"payloadHash\",payload,\"occurredAt\") VALUES (?::uuid,?,?::uuid,?,?,?,?,?,?) ON CONFLICT (\"stepAttemptId\",\"observationId\") DO NOTHING",attempt.get("id"),attempt.get("invocationId"),attempt.get("executionId"),id,provider,child,hash,o,occurred);ObjectNode after=t.one("SELECT * FROM delegation_observations WHERE \"stepAttemptId\"=?::uuid AND \"observationId\"=?",attempt.get("id"),id);if(after!=null&&!hash.equals(Json.text(after,"payloadHash")))t.insert("delegation_observation_conflicts",Json.object("stepAttemptId",attempt.get("id"),"executionId",attempt.get("executionId"),"observationId",id,"payloadHash",hash,"payload",o,"conflictKind","identity_payload"));}c.releaseSavepoint(checkpoint);}catch(Exception error){try{if(checkpoint!=null)c.rollback(checkpoint);}catch(SQLException failure){throw new Db.Failure(failure);}System.err.println("Delegation observations rejected for invocation "+Json.text(attempt,"invocationId"));}}
    private int parentDepth(Db t,String execution){return count(t,"SELECT COALESCE(MAX(\"childDepth\"),0) n FROM delegation_requests WHERE \"childExecutionId\"=?::uuid",execution);}
    private Integer runDepth(Db t,String execution){String current=execution;Set<String> seen=new HashSet<>();for(int hop=0;hop<4;hop++){if(!seen.add(current))throw new IllegalStateException("Delegation lineage cycle");ObjectNode r=t.one("SELECT \"parentExecutionId\" FROM delegation_requests WHERE \"childExecutionId\"=?::uuid ORDER BY \"createdAt\" DESC LIMIT 1",current);if(r==null)break;current=Json.text(r,"parentExecutionId");}ObjectNode run=t.one("SELECT config FROM coordination_runs WHERE \"executionId\"=?::uuid",current);return run!=null&&run.path("config").has("delegationDepthMax")?run.path("config").path("delegationDepthMax").intValue():null;}
    private ObjectNode lock(Db t,String attempt,String request){ObjectNode r=t.one("SELECT * FROM delegation_requests WHERE \"parentAttemptId\"=?::uuid AND \"requestId\"=? FOR UPDATE",attempt,request);if(r==null)throw new IllegalArgumentException("Delegation request not found");return r;}
    private ObjectNode decide(Db t,JsonNode r,String decision,String reason,String child){ObjectNode saved=t.one("UPDATE delegation_requests SET status=?,\"decisionNote\"=?,\"decidedAt\"=?,\"childExecutionId\"=COALESCE(?::uuid,\"childExecutionId\") WHERE id=?::uuid AND status='PENDING' RETURNING *",decision,reason,Instant.now(),child,r.get("id"));return outcome(saved==null?t.one("SELECT * FROM delegation_requests WHERE id=?::uuid",r.get("id")):saved);}
    private static ObjectNode outcome(JsonNode r){return Json.object("decision",r.get("status"),"childExecutionId",Json.get(r,"childExecutionId"),"reason",r.hasNonNull("decisionNote")?r.get("decisionNote"):Json.value("Already decided"));}
    private static int count(Db t,String sql,Object...args){return Json.integer(t.one(sql,args),"n",0);}
}
